30	// The people on the active sheet, in the order they were added, and the one form that adds a
31	// person or, once a person's editor is opened, saves changes to them. Each person's row lists their
32	// claims, what they have claimed (its OPEN and SETTLED claims, though a held person's OPEN ones count in
33	// no total) and what is due on it: the sum of those
34	// claims' rounded dues; the sheet's
35	// claimed-total and due-total add everyone's up (a due-total of n/a is skipped). Each person, and the sheet,
36	// also shows how many of the claims that count are overdue and the sum of their dues (n/a ones skipped).
37	@Component({
38	  selector: 'app-people',
39	  imports: [ReactiveFormsModule, Claims, Periods, Rates, Summary],
40	  template: `
41	    <app-rates [grades]="grades" [rates]="rates()" [current]="rateByGrade()" (saved)="rateSaved($event)" />
42	    <app-periods [periods]="periods()" [dueTotals]="periodDueTotals()" (saved)="periodSaved($event)" />
43	    <app-summary
44	      [grades]="gradeSummary()"
