52	        <label for="person-form-name">Name</label>
53	        <input id="person-form-name" data-testid="person-form-name" formControlName="name" />
54	        <label for="person-form-grade">Grade</label>
55	        <select id="person-form-grade" data-testid="person-form-grade" formControlName="grade">
56	          @for (g of grades; track g) {
57	            <option [value]="g">{{ g }}</option>
58	          }
59	        </select>
60	        @if (editingId() !== null) {
61	          <label for="person-form-grade-from">Grade from</label>
62	          <input id="person-form-grade-from" type="date" data-testid="person-form-grade-from" formControlName="gradeFrom" />
63	        }
64	        <button type="submit" data-testid="person-form-submit">
65	          {{ editingId() === null ? 'Add person' : 'Save person' }}
66	        </button>
67	        @if (editingId() !== null) {
68	          <button type="button" data-testid="person-form-cancel" (click)="reset()">Cancel</button>
69	        }
70	      </form>
71	      @if (formError(); as e) {
72	        <p role="alert" data-testid="person-form-error">{{ e }}</p>
73	      }
74	      <form [formGroup]="quickForm" (ngSubmit)="quickAdd()" data-testid="quick-add" aria-label="Quick add a claim">
75	        <label for="quick-name">Name</label>
76	        <input id="quick-name" data-testid="quick-name" formControlName="name" />
77	        <label for="quick-amount">Amount</label>
78	        <input id="quick-amount" data-testid="quick-amount" formControlName="amount" inputmode="decimal" />
79	        <button type="submit" data-testid="quick-submit">Quick add</button>
80	      </form>
