82	        <p role="alert" data-testid="quick-error">{{ e }}</p>
83	      }
84	      <label>
85	        <input type="checkbox" data-testid="show-retired" [checked]="showRetired()" (change)="toggleRetired($event)" />
86	        Show retired
87	      </label>
88	      <p>Claimed total: <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
89	      <p>Due total: <strong data-testid="rollup-due-total">{{ dueTotal() }}</strong></p>
90	      <p>Overdue: <strong data-testid="rollup-overdue-count">{{ overdueCount() }}</strong></p>
91	      <p>Overdue total: <strong data-testid="rollup-overdue-total">{{ overdueTotal() }}</strong></p>
92	      <table data-testid="people-list">
93	        <thead>
94	          <tr>
95	            <th scope="col">Name</th>
96	            <th scope="col">Grade</th>
97	            <th scope="col">Claimed</th>
98	            <th scope="col">Due</th>
99	            <th scope="col">Statements</th>
100	            <th scope="col">Last stated</th>
101	            <th scope="col">Stated on</th>
102	            <th scope="col">Retired</th>
103	            <th scope="col">Retired from</th>
104	            <th scope="col">On hold</th>
105	            <th scope="col">Overdue</th>
